// Stand-in for desktop/src/backend/index.ts until the native backend lands. It starts nothing, so the
// app runs without a database and shows its "could not sign you in" page. The build (scripts/desktop/
// build.mjs) and desktop/tsconfig.json pick the real module automatically once it exists; then delete this.
import { mkdir } from "node:fs/promises";
import path from "node:path";

export type BackendPaths = { resources: string; home: string };
export type Progress = (step: { id: string; label: string; state: "running" | "done" | "error"; detail?: string }) => void;
export type RunningBackend = {
  env: Record<string, string>;
  stop(): Promise<void>;
  onExit(cb: (service: string, code: number | null) => void): void;
};

export async function startBackend(paths: BackendPaths, progress: Progress): Promise<RunningBackend> {
  progress({ id: "database", label: "Preparing the database (stub)", state: "running" });
  const data = path.join(paths.home, "data"), workflow = path.join(paths.home, "workflow");
  await Promise.all([mkdir(data, { recursive: true }), mkdir(workflow, { recursive: true })]);
  progress({ id: "database", label: "Preparing the database (stub)", state: "done" });
  return { env: { MONEO_DATA_DIR: data, WORKFLOW_LOCAL_DATA_DIR: workflow }, stop: async () => {}, onExit: () => {} };
}

export async function backup(paths: BackendPaths, reason: string): Promise<string> {
  const folder = path.join(paths.home, "backups", `${new Date().toISOString().replace(/[:.]/g, "-")}-${reason}`);
  await mkdir(folder, { recursive: true });
  return folder;
}

export async function restore(): Promise<void> {}

// Which addresses the app window may show, and which go to the system browser instead.
// Pure functions, so the rules are testable without Electron.

const LOOPBACK = new Set(["localhost", "127.0.0.1"]);

function parse(url: string) {
  try { return new URL(url); } catch { return null; }
}

/** Moneo's own server on this computer: the only pages the app window loads. */
export function isAppUrl(url: string, port: number) {
  const parsed = parse(url);
  return parsed?.protocol === "http:" && LOOPBACK.has(parsed.hostname) && parsed.port === String(port);
}

/** What may open in the system browser: https anywhere (sign-ins, banks), or Moneo itself. */
export function isExternalAllowed(url: string, port: number) {
  return parse(url)?.protocol === "https:" || isAppUrl(url, port);
}

/** Enable Banking's consent pages; the bank sends the browser back to https://localhost:3443. */
export function isBankConsent(url: string) {
  const host = parse(url)?.hostname ?? "";
  return host === "enablebanking.com" || host.endsWith(".enablebanking.com");
}

import { describe, expect, it } from "vitest";
import { isAppUrl, isExternalAllowed } from "./navigation";

// The app window has the owner's session and microphone access; a lookalike host or another local
// server must never load inside it.
describe("desktop navigation rules", () => {
  it("keeps only Moneo's own loopback port in the window", () => {
    expect(isAppUrl("http://localhost:47300/settings", 47300)).toBe(true);
    expect(isAppUrl("http://127.0.0.1:47300/api/ai/chatgpt/callback?code=x", 47300)).toBe(true);
    expect(isAppUrl("http://localhost:3000/", 47300)).toBe(false);
    expect(isAppUrl("http://localhost.evil.example:47300/", 47300)).toBe(false);
    expect(isAppUrl("https://localhost:47300/", 47300)).toBe(false);
    expect(isAppUrl("file:///etc/passwd", 47300)).toBe(false);
  });

  it("sends only https or Moneo itself to the system browser", () => {
    expect(isExternalAllowed("https://auth.openai.com/oauth/authorize", 47300)).toBe(true);
    expect(isExternalAllowed("http://localhost:47300/", 47300)).toBe(true);
    expect(isExternalAllowed("http://example.com/", 47300)).toBe(false);
    expect(isExternalAllowed("file:///C:/Windows/System32/calc.exe", 47300)).toBe(false);
    expect(isExternalAllowed("javascript:alert(1)", 47300)).toBe(false);
  });
});

import { app } from "electron";
import { existsSync, mkdirSync, readFileSync, writeFileSync, appendFileSync } from "node:fs";
import path from "node:path";

// Bundled resources: next to app.asar when packaged, desktop/.build while developing.
export const resources = () => app.isPackaged ? process.resourcesPath : path.join(app.getAppPath(), ".build");

/** Per-user data folder. Tests point MONEO_DESKTOP_HOME at a temporary folder. Call before `ready`. */
export function setupHome() {
  const home = process.env.MONEO_DESKTOP_HOME ? path.resolve(process.env.MONEO_DESKTOP_HOME) : app.getPath("userData");
  app.setPath("userData", home);
  // Keep Chromium's own files (cookies, caches) apart from the database and backups.
  app.setPath("sessionData", path.join(home, "chromium"));
  mkdirSync(path.join(home, "logs"), { recursive: true });
  app.setAppLogsPath(path.join(home, "logs"));
  return home;
}

export const home = () => app.getPath("userData");
export const logsDir = () => path.join(home(), "logs");
export const backupsDir = () => path.join(home(), "backups");
export const dataDir = () => path.join(home(), "data");

/** platform-arch folder of the bundled native tools, e.g. win-x64. */
export const platformKey = () => `${process.platform === "win32" ? "win" : process.platform === "darwin" ? "mac" : "linux"}-${process.arch}`;

export function log(message: string, file = "main.log") {
  const line = `${new Date().toISOString()} ${message}\n`;
  try { appendFileSync(path.join(logsDir(), file), line); } catch { /* logging must never stop Moneo */ }
  if (!app.isPackaged) process.stdout.write(line);
}

// The shell's own settings. The backend keeps its secrets in config.json; these are kept apart so the two never race.
export type ShellSettings = { port?: number; trayNoticeShown?: boolean; lastBackupAt?: string; bankCertificateTrusted?: boolean };
const settingsFile = () => path.join(home(), "shell.json");

export function readSettings(): ShellSettings {
  try { return existsSync(settingsFile()) ? JSON.parse(readFileSync(settingsFile(), "utf8")) as ShellSettings : {}; } catch { return {}; }
}

export function updateSettings(patch: ShellSettings) {
  const next = { ...readSettings(), ...patch };
  writeFileSync(settingsFile(), JSON.stringify(next, null, 2), { mode: 0o600 });
  return next;
}

import { createServer } from "node:net";
import { log, readSettings, updateSettings } from "./paths";

// Phone access, Scalable's registered return address and a pending ChatGPT sign-in all name this
// port, so it stays the same from run to run. 3000 is left to source checkouts.
export const DEFAULT_PORT = 47300;

function listen(port: number) {
  return new Promise<number | null>(resolve => {
    const server = createServer();
    server.once("error", () => resolve(null));
    server.listen(port, "127.0.0.1", () => {
      const address = server.address();
      server.close(() => resolve(typeof address === "object" && address ? address.port : null));
    });
  });
}

export async function choosePort() {
  const saved = readSettings().port;
  const wanted = saved ?? DEFAULT_PORT;
  if (await listen(wanted) === wanted) {
    if (!saved) updateSettings({ port: wanted });
    return wanted;
  }
  const free = await listen(0);
  if (!free) throw new Error("No free local port for Moneo.");
  // First run: adopt the free port for good. Later runs: borrow it, and try the usual one next time.
  if (!saved) updateSettings({ port: free });
  log(`Port ${wanted} is busy; using ${free}${saved ? " for this run" : ""}.`);
  return free;
}

import { utilityProcess, type UtilityProcess } from "electron";
import { createWriteStream } from "node:fs";
import path from "node:path";
import { log, logsDir } from "./paths";

// Host variables the server needs to run on each OS. Nothing else from the shell's environment is
// passed on, so a developer's NEXT_PUBLIC_*, NODE_OPTIONS or .env-style variables never leak in.
const HOST_VARS = ["PATH", "Path", "PATHEXT", "SystemRoot", "SYSTEMROOT", "windir", "TEMP", "TMP", "TMPDIR", "HOME", "USERPROFILE", "APPDATA", "LOCALAPPDATA", "ProgramData", "LANG", "LC_ALL", "TZ"];

export type NextServerOptions = { appDir: string; port: number; env: Record<string, string> };

const READY_TIMEOUT = 90_000;

/** The Next.js standalone server in a utility process, restarted with backoff when it crashes. */
export class NextServer {
  private child?: UtilityProcess;
  private stopping = false;
  private restarts = 0;
  private restartTimer?: NodeJS.Timeout;
  private output = createWriteStream(path.join(logsDir(), "next.log"), { flags: "a" });
  private recent: string[] = [];

  constructor(private options: NextServerOptions, private onDown: (error: Error) => void) {}

  get url() { return `http://localhost:${this.options.port}`; }
  get pid() { return this.child?.pid; }

  async start() {
    this.stopping = false;
    const startedAt = Date.now();
    const child = this.spawn();
    await this.waitReady(child);
    child.once("exit", code => {
      if (this.stopping || this.child !== child) return;
      log(`Next server exited with ${code}`);
      // A server that ran for a while earns a fresh backoff.
      if (Date.now() - startedAt > 60_000) this.restarts = 0;
      this.scheduleRestart();
    });
  }

  private spawn() {
    const host = Object.fromEntries(HOST_VARS.flatMap(name => process.env[name] ? [[name, process.env[name]!]] : []));
    const env = {
      ...host,
      ...this.options.env,
      PORT: String(this.options.port),
      HOSTNAME: "127.0.0.1",
      NEXT_PUBLIC_APP_URL: `http://localhost:${this.options.port}`,
      MONEO_DESKTOP: "1",
      NODE_ENV: "production",
      NEXT_TELEMETRY_DISABLED: "1",
    };
    const child = utilityProcess.fork(path.join(this.options.appDir, "server.js"), [], {
      cwd: this.options.appDir, env, stdio: "pipe", serviceName: "Moneo server",
    });
    const record = (chunk: Buffer) => {
      this.output.write(chunk);
      this.recent.push(...chunk.toString().split(/\r?\n/).filter(Boolean));
      this.recent.splice(0, Math.max(0, this.recent.length - 20));
    };
    child.stdout?.on("data", record);
    child.stderr?.on("data", record);
    this.child = child;
    log(`Next server starting on port ${this.options.port}`);
    return child;
  }

  private async waitReady(child: UtilityProcess) {
    let exited: number | null | undefined;
    child.once("exit", code => { exited = code; });
    const deadline = Date.now() + READY_TIMEOUT;
    while (Date.now() < deadline) {
      if (exited !== undefined) throw new Error(`The Moneo server stopped while starting (exit ${exited}).\n${this.recent.slice(-8).join("\n")}`);
      try {
        // The bearer header keeps the proxy from signing the owner in for every probe.
        const response = await fetch(`http://127.0.0.1:${this.options.port}/api/health`, { headers: { authorization: "Bearer readiness" }, signal: AbortSignal.timeout(5_000) });
        if (response.status < 500) { log("Next server is ready"); return; }
      } catch { /* not listening yet */ }
      await new Promise(resolve => setTimeout(resolve, 250));
    }
    child.kill();
    throw new Error(`The Moneo server did not answer within ${READY_TIMEOUT / 1000} seconds.\n${this.recent.slice(-8).join("\n")}`);
  }

  private scheduleRestart() {
    const delay = Math.min(30_000, 1_000 * 2 ** this.restarts++);
    log(`Restarting the Next server in ${delay} ms`);
    this.restartTimer = setTimeout(() => {
      this.start().catch(error => {
        log(`Next server restart failed: ${error instanceof Error ? error.message : error}`);
        if (this.restarts >= 6) this.onDown(error instanceof Error ? error : new Error(String(error)));
        else this.scheduleRestart();
      });
    }, delay);
  }

  async stop() {
    this.stopping = true;
    clearTimeout(this.restartTimer);
    const child = this.child;
    this.child = undefined;
    if (!child?.pid) return;
    await new Promise<void>(resolve => {
      const force = setTimeout(resolve, 10_000);
      child.once("exit", () => { clearTimeout(force); resolve(); });
      child.kill();
    });
    log("Next server stopped");
  }
}

import { execFile } from "node:child_process";
import { existsSync, mkdirSync } from "node:fs";
import path from "node:path";
import { promisify } from "node:util";
import { dataDir, home, log, platformKey, resources } from "./paths";

// Enable Banking only returns to https addresses, so Moneo answers on https://localhost:3443
// (lib/bank/return-listener.ts) with a certificate from the bundled mkcert. Two steps:
// 1. ensureBankCertificate, silently on every start: makes the certificate (and a private signing
//    authority kept in the Moneo folder) so the listener can start. Nothing is trusted yet.
// 2. trustBankCertificate, the first time the owner opens a bank's consent page: asks the computer
//    to trust that authority, which shows the system's own confirmation once.
const run = promisify(execFile);

const mkcert = () => path.join(resources(), "backend", platformKey(), process.platform === "win32" ? "mkcert.exe" : "mkcert");
const caRoot = () => path.join(home(), "mkcert");
const files = () => ({ key: path.join(dataDir(), "localhost-key.pem"), cert: path.join(dataDir(), "localhost.pem") });

function env(trustStores: string) {
  return { ...process.env, CAROOT: caRoot(), TRUST_STORES: trustStores };
}

export async function ensureBankCertificate() {
  const { key, cert } = files();
  if (existsSync(key) && existsSync(cert)) return true;
  if (!existsSync(mkcert())) { log("mkcert is not bundled; bank connections cannot return to Moneo"); return false; }
  mkdirSync(dataDir(), { recursive: true });
  mkdirSync(caRoot(), { recursive: true });
  try {
    await run(mkcert(), ["-cert-file", cert, "-key-file", key, "localhost", "127.0.0.1", "::1"], { env: env("system"), timeout: 30_000, windowsHide: true });
    log("Bank return certificate created");
    return true;
  } catch (error) {
    log(`Could not create the bank return certificate: ${error instanceof Error ? error.message : error}`);
    return false;
  }
}

/** Trusts Moneo's own signing authority in the user's certificate store (not machine-wide). */
export async function trustBankCertificate() {
  const rootCa = path.join(caRoot(), "rootCA.pem");
  if (!existsSync(rootCa)) return false;
  try {
    if (process.platform === "darwin") {
      // mkcert -install would need sudo for the system keychain; the login keychain asks in a normal window.
      const keychain = path.join(process.env.HOME ?? "", "Library", "Keychains", "login.keychain-db");
      await run("/usr/bin/security", ["add-trusted-cert", "-r", "trustRoot", "-k", keychain, rootCa], { timeout: 120_000 });
    } else {
      // Windows: the current user's root store (Windows asks once). Linux: Chrome/Firefox's NSS store, which needs certutil.
      await run(mkcert(), ["-install"], { env: env(process.platform === "win32" ? "system" : "nss"), timeout: 120_000, windowsHide: true });
    }
    log("Bank return certificate trusted");
    return true;
  } catch (error) {
    log(`Could not trust the bank return certificate: ${error instanceof Error ? error.message : error}`);
    return false;
  }
}

// Preload for the local setup/status window only (the app window has none). It exposes progress
// updates and four buttons, nothing else; the main process checks every call's sender.
import { contextBridge, ipcRenderer } from "electron";

contextBridge.exposeInMainWorld("moneoSetup", {
  state: () => ipcRenderer.invoke("setup:state"),
  onState: (callback: (state: unknown) => void) => { ipcRenderer.on("setup:state", (_event, state) => callback(state)); },
  retry: () => ipcRenderer.invoke("setup:retry"),
  openLogs: () => ipcRenderer.invoke("setup:open-logs"),
  restoreBackup: () => ipcRenderer.invoke("setup:restore"),
  quit: () => ipcRenderer.invoke("setup:quit"),
});

